import{_ as i,C as e,o as r,c as s,a6 as n,E as o}from"./chunks/framework.DycQjAfF.js";const p=JSON.parse('{"title":"Alur Stock Opname","description":"Urutan kerja menghitung stok fisik, membandingkan dengan catatan, dan menangani selisih.","frontmatter":{"title":"Alur Stock Opname","description":"Urutan kerja menghitung stok fisik, membandingkan dengan catatan, dan menangani selisih.","status":"ditinjau","dasar":"Instruksi Kerja Stock Opname Harian Gudang Teknik dan materi Gudang Teknik tentang cycle counting","diperbarui":"2026-10-20T00:00:00.000Z","kategori":"Alur Kerja","sumber":["ik-gudang-teknik","ppt-gudang-teknik"],"kata_kunci":["stock opname","stock opname harian","stock sheet","stock keeper","hitung fisik","cycle counting","selisih","penyesuaian stok","adjustment","akurasi stok","cut-off"]},"headers":[],"relativePath":"alur-kerja/stock-opname.md","filePath":"alur-kerja/stock-opname.md"}'),l={name:"alur-kerja/stock-opname.md"};function k(g,a,u,d,h,c){const t=e("MermaidDiagram");return r(),s("div",null,[a[0]||(a[0]=n('<h1 id="alur-stock-opname" tabindex="-1">Alur Stock Opname <a class="header-anchor" href="#alur-stock-opname" aria-label="Permalink to &quot;Alur Stock Opname&quot;">​</a></h1><p class="lead">Stock opname membandingkan jumlah barang di rak dengan jumlah di catatan. Di Gudang Teknik, stock opname dilakukan setiap hari secara bergilir (<em>cycle count</em>). Tujuannya menemukan selisih, mencari penyebabnya, lalu memperbaiki catatan secara sah.</p><h2 id="ringkasan-proses" tabindex="-1">Ringkasan proses <a class="header-anchor" href="#ringkasan-proses" aria-label="Permalink to &quot;Ringkasan proses&quot;">​</a></h2><table class="tabel-tumpuk tanpa-kepala" tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Tujuan</strong></td><td>Menjaga akurasi stok (stock accuracy)</td></tr><tr><td><strong>Pemicu</strong></td><td>Jadwal harian bergilir per kategori barang, terutama fast moving, barang bernilai tinggi, dan barang yang baru masuk atau keluar</td></tr><tr><td><strong>Pihak yang terlibat</strong></td><td>Stock Keeper (menghitung) dan Supervisor atau Kepala Gudang (memvalidasi)</td></tr><tr><td><strong>Input</strong></td><td>Stock sheet harian atau kartu stok, alat tulis, dan clipboard</td></tr><tr><td><strong>Output</strong></td><td>Lembar hasil hitung, daftar selisih beserta penyebabnya, laporan opname</td></tr><tr><td><strong>SOP terkait</strong></td><td><a href="/WareHouse/sop/stock-opname">Stock Opname</a></td></tr></tbody></table><h2 id="diagram" tabindex="-1">Diagram <a class="header-anchor" href="#diagram" aria-label="Permalink to &quot;Diagram&quot;">​</a></h2>',5)),o(t,{code:"flowchart%20TD%0A%20%20accTitle%3A%20Alur%20stock%20opname%20harian%0A%20%20accDescr%3A%20Siapkan%20stock%20sheet%20kategori%20hari%20ini%2C%20hentikan%20transaksi%20sementara%2C%20hitung%20fisik%2C%20lalu%20bandingkan%20dengan%20catatan.%20Selisih%20dihitung%20ulang%2C%20ditelusuri%2C%20dilaporkan%2C%20dan%20baru%20disesuaikan%20setelah%20disetujui.%0A%20%20A(%5BKategori%20barang%20hari%20ini%5D)%20--%3E%20B%5BSiapkan%20stock%20sheet%3Cbr%2F%3Eatau%20kartu%20stok%5D%0A%20%20B%20--%3E%20C%5BHentikan%20sementara%20transaksi%3Cbr%2F%3Edi%20area%20yang%20dihitung%5D%0A%20%20C%20--%3E%20D%5BHitung%20fisik%20per%20lokasi%2C%3Cbr%2F%3Etulis%20di%20lembar%20hitung%5D%0A%20%20D%20--%3E%20E%5BBandingkan%20dengan%20catatan%5D%0A%20%20E%20--%3E%20F%7BAda%20selisih%3F%7D%0A%20%20F%20--%20Tidak%20--%3E%20K%5BTandai%20item%20cocok%5D%0A%20%20F%20--%20Ya%20--%3E%20G%5BHitung%20ulang%3Cbr%2F%3Eoleh%20orang%20berbeda%5D%0A%20%20G%20--%3E%20H%7BMasih%20selisih%3F%7D%0A%20%20H%20--%20Tidak%20--%3E%20K%0A%20%20H%20--%20Ya%20--%3E%20I%5BTelusuri%20penyebab%3A%20transaksi%20belum%3Cbr%2F%3Edicatat%2C%20salah%20lokasi%2C%20salah%20satuan%5D%0A%20%20I%20--%3E%20J%5BLaporkan%20selisih%20%26%20penyebabnya%5D%0A%20%20J%20--%3E%20L%7BDivalidasi%20Supervisor%2F%3Cbr%2F%3EKepala%20Gudang%3F%7D%0A%20%20L%20--%20Ya%20--%3E%20M%5B(Sesuaikan%20catatan%20stok)%5D%0A%20%20L%20--%20Tidak%20--%3E%20I%0A%20%20K%20--%3E%20N%5BSusun%20laporan%20opname%5D%0A%20%20M%20--%3E%20N%0A%20%20N%20--%3E%20O(%5BSelesai%5D)%0A"}),a[1]||(a[1]=n('<h2 id="langkah-tertulis" tabindex="-1">Langkah tertulis <a class="header-anchor" href="#langkah-tertulis" aria-label="Permalink to &quot;Langkah tertulis&quot;">​</a></h2><ol><li><strong>Lihat jadwal hari ini.</strong> Setiap hari, kategori barang yang berbeda dihitung secara bergiliran (<em>cycle count</em>), dengan fokus pada barang fast moving, barang bernilai tinggi, dan barang yang baru masuk atau keluar.</li><li><strong>Siapkan stock sheet harian atau kartu stok</strong> untuk kategori tersebut.</li><li><strong>Hentikan sementara transaksi</strong> di area yang dihitung. Jika tidak memungkinkan, catat waktu batasnya (<em>cut-off</em>) agar transaksi setelahnya tidak tercampur.</li><li><strong>Hitung fisik per lokasi.</strong> Tulis hasilnya apa adanya, termasuk barang rusak dan barang tanpa label.</li><li><strong>Bandingkan</strong> hasil hitung dengan catatan.</li><li><strong>Jika ada selisih, hitung ulang</strong> sebaiknya oleh orang lain.</li><li><strong>Telusuri penyebab</strong> selisih yang tetap ada: transaksi yang belum dicatat, barang di lokasi lain, salah satuan, atau salah kode.</li><li><strong>Laporkan</strong> selisih dan penyebabnya ke Supervisor atau Kepala Gudang. Catatan stok hanya disesuaikan setelah hasilnya divalidasi.</li><li><strong>Susun laporan opname</strong>, termasuk temuan lain seperti barang rusak, label hilang, atau calon barang write off.</li></ol><h2 id="potensi-kesalahan" tabindex="-1">Potensi kesalahan <a class="header-anchor" href="#potensi-kesalahan" aria-label="Permalink to &quot;Potensi kesalahan&quot;">​</a></h2><ul><li><strong>Menghitung sambil ada transaksi berjalan.</strong> Hasilnya tidak bisa dibandingkan dengan catatan.</li><li><strong>Langsung mengubah angka di catatan agar cocok.</strong> Penyebab selisih tidak pernah ditemukan dan bisa terulang.</li><li><strong>Melewatkan lokasi cadangan</strong>, misalnya barang yang sama disimpan di dua rak.</li><li><strong>Tidak mencatat kondisi barang.</strong> Barang rusak ikut terhitung sebagai stok yang siap pakai.</li></ul>',4))])}const b=i(l,[["render",k]]);export{p as __pageData,b as default};
